const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:3000', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({waitUntil:'networkidle'});
  console.log('initial', await page.locator('#money').innerText(), await page.locator('#parkMap .plot').count());
  await page.locator('[data-view="shop"]').first().click();
  await page.locator('.shop-tab[data-category="decor"]').click();
  await page.locator('.shop-item').filter({hasText:'Wildflower Patch'}).locator('.buy-btn').click();
  await page.locator('#parkMap .open-plot').first().click();
  console.log('placed', await page.locator('#parkMap .occupied').count(), 'money', await page.locator('#money').innerText());
  await page.locator('#collectBtn').click();
  await page.locator('#feedBtn').click();
  console.log('economy', await page.locator('#money').innerText(), 'hunger', await page.locator('#hungerText').innerText());
  await page.locator('[data-view="battle"]').first().click();
  await page.locator('#startBattle').click();
  await page.evaluate(() => { Math.random = () => 0; });
  for (const move of ['leaf','stomp','stomp']) {
    await page.locator(`.move-btn[data-move="${move}"]`).click();
    if (move !== 'stomp' || (await page.locator('#battleResult').isVisible())) await page.waitForTimeout(800);
    else await page.waitForTimeout(800);
    if (await page.locator('#battleResult').isVisible()) break;
  }
  console.log('battle', await page.locator('#resultKicker').innerText(), 'progress', await page.locator('#expeditionText').innerText());
  await page.locator('#continueBtn').click();
  await page.reload({waitUntil:'networkidle'});
  console.log('persist', await page.locator('#money').innerText(), 'placed', await page.locator('#parkMap .occupied').count());
  await page.evaluate(() => localStorage.clear());
  await page.reload({waitUntil:'networkidle'});
  await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/latest.jpg',type:'jpeg',quality:78,fullPage:false});
  console.log('errors', JSON.stringify(errors));
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

